'use strict';

const cors = require('cors');
const fs = require('fs');
const path = require('path');
const runner = require('../test-runner');

module.exports = function (app) {

  app.route('/_api/server.js')
    .get(function(req, res, next) {
      const candidates = [
        path.join(__dirname, '..', 'server.js'),
        path.join(__dirname, 'server.js'),
        path.join(process.cwd(), 'server.js')
      ];
      const target = candidates.find(p => fs.existsSync(p)) || candidates[0];
      fs.readFile(target, function(err, data) {
        if(err) return res.type('txt').send('/* server.js */');
        res.type('txt').send(data.toString());
      });
    });

  app.route('/_api/routes/api.js')
    .get(function(req, res, next) {
      const candidates = [
        path.join(__dirname, 'api.js'),
        path.join(__dirname, 'routes', 'api.js'),
        path.join(process.cwd(), 'routes', 'api.js')
      ];
      const target = candidates.find(p => fs.existsSync(p)) || candidates[0];
      fs.readFile(target, function(err, data) {
        if(err) return res.type('txt').send('/* routes/api.js */');
        res.type('txt').send(data.toString());
      });
    });

  app.get('/_api/get-tests', cors(), function(req, res, next){
    if(process.env.NODE_ENV === 'test') return next();
    res.json({status: 'unavailable'});
  },
  function(req, res, next){
    if(runner.report) {
      return res.json(testFilter(runner.report, req.query.type, req.query.n));
    }
    
    // In serverless environments, trigger runner if not yet run
    try {
      runner.run();
    } catch(e) {
      // Runner might already be running
    }

    let completed = false;
    const timeout = setTimeout(function() {
      if (!completed) {
        completed = true;
        res.json(testFilter(runner.report || [], req.query.type, req.query.n));
      }
    }, 3000);

    runner.once('done', function(report){
      if (!completed) {
        completed = true;
        clearTimeout(timeout);
        process.nextTick(() => res.json(testFilter(report || runner.report || [], req.query.type, req.query.n)));
      }
    });
  });
};

function testFilter(tests, type, n) {
  let out;
  switch (type) {
    case 'unit' :
      out = tests.filter(t => t.context && t.context.match('Unit Tests'));
      break;
    case 'functional':
      out = tests.filter(t => t.context && t.context.match('Functional Tests') && !t.title.match('#example'));
      break;
    default:
      out = tests;
  }
  if(n !== undefined) {
    return out[n] || out;
  }
  return out;
}